import { useEffect, useMemo, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { adminControlApi } from "../api/adminControl.js";
import { hasOperationalCapability } from "../lib/authz.js";
import { Icon } from "../lib/icons.jsx";
import { useAsyncData } from "../hooks/useAsyncData.js";
import { ConfirmDialog } from "../components/shared/ConfirmDialog.jsx";
import { EmptyState, ErrorPanel, LoadingPanel, Page } from "../components/ui/index.jsx";
import { StatsGrid } from "../components/shared/StatsGrid.jsx";

const TABS = [
  ["overview", "Overview", "overview.view", "analytics"],
  ["users", "Users", "users.view", "user"],
  ["purchases", "Purchases", "payments.view", "file"],
  ["subscriptions", "Subscriptions", "subscriptions.view", "layers"],
  ["notifications", "Notifications", "notifications.view", "bell"],
  ["reports", "Reports", "moderation.view", "messages"],
  ["audit", "Audit log", "audit.view", "activity"],
  ["settings", "Settings", "configuration.view", "settings"],
  ["system", "System", "system_health.view", "activity"],
  ["exports", "Exports", "reports.export", "file"]
];

function humanize(value) {
  return String(value || "Not available").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function shortDate(value) {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString();
}

function money(value, currency = "USD", exponent = 2) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) return "—";
  try { return new Intl.NumberFormat(undefined, { style: "currency", currency }).format(amount / Math.pow(10, Number(exponent) || 2)); }
  catch { return `${amount} ${currency}`; }
}

function Notice({ error, message }) {
  const fields = error?.fields && typeof error.fields === "object"
    ? Object.entries(error.fields).flatMap(([name, values]) => `${humanize(name)}: ${Array.isArray(values) ? values.join(" ") : values}`)
    : [];
  if (!error && !message) return null;
  return <div className={`form-alert ${error ? "error" : "success"}`} role={error ? "alert" : "status"}>{error?.message || message}{fields.map((field) => <small key={field}>{field}</small>)}</div>;
}

function Pager({ page, count, onPage }) {
  const canBack = page > 1;
  const canNext = page * 25 < count;
  return <div className="operations-pager"><span>{count} server record{count === 1 ? "" : "s"}</span><div><button className="btn btn-soft compact" type="button" disabled={!canBack} onClick={() => onPage(page - 1)}>Previous</button><button className="btn btn-soft compact" type="button" disabled={!canNext} onClick={() => onPage(page + 1)}>Next</button></div></div>;
}

function AdminTabs({ operationsSession, active }) {
  return <nav className="operations-tabs" aria-label="Operations areas">
    {TABS.filter(([, , capability]) => hasOperationalCapability(operationsSession, capability)).map(([key, label, , icon]) => <Link key={key} to={`/operations/admin/${key}`} className={active === key ? "active" : ""}><Icon name={icon} size={16} />{label}</Link>)}
  </nav>;
}

function FormButton({ pending, children, className = "btn btn-primary", ...props }) {
  return <button className={className} type="submit" disabled={pending} {...props}>{pending ? "Working…" : children}</button>;
}

function Overview() {
  const data = useAsyncData(() => Promise.all([adminControlApi.overview(), adminControlApi.analytics()]).then(([overview, analytics]) => ({ overview, analytics })), []);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const { analytics } = data.data;
  return <>
    <StatsGrid cards={[
      ["Users", analytics.users.total, "user", `${analytics.users.new_registrations} new`],
      ["Active subscriptions", analytics.subscriptions.active, "layers", `${analytics.subscriptions.trial} trial`],
      ["Net revenue", money(analytics.revenue.net_minor), "analytics", `${analytics.revenue.failed_payments} failed`],
      ["Focus time", `${Math.round(analytics.learning.focus_seconds / 3600)}h`, "clock", `${analytics.learning.focus_sessions} sessions`],
      ["Quiz attempts", analytics.learning.quiz_attempts, "help", `${analytics.learning.pass_rate ?? "—"}% pass`]
    ]} />
    <section className="community-top">
      <article className="panel announcement-panel"><div className="panel-title"><h2>Subscription health</h2><span>Database aggregate</span></div><div className="operations-facts"><p><b>{analytics.subscriptions.upcoming_expirations}</b> subscriptions expire in the next 14 days.</p><p><b>{analytics.subscriptions.churn_rate ?? "—"}%</b> churn over the selected window.</p><p><b>{analytics.subscriptions.renewals}</b> subscription period renewals.</p></div></article>
      <article className="panel announcement-panel"><div className="panel-title"><h2>Learning activity</h2><span>Database aggregate</span></div><div className="operations-facts"><p><b>{analytics.learning.active_learners}</b> active Focus learners.</p><p><b>{analytics.learning.material_completions}</b> material completions.</p><p><b>{analytics.learning.average_score ?? "—"}</b> average assessment score.</p></div></article>
    </section>
    <section className="panel list-panel"><div className="panel-title"><h2>Revenue trend</h2><span>{analytics.period.from} to {analytics.period.to}</span></div>{analytics.revenue.trend.length ? analytics.revenue.trend.map((point) => <article className="list-row" key={point.day}><span className="stat-icon"><Icon name="analytics" /></span><div><h2>{point.day}</h2><p>{point.count} settled payment{point.count === 1 ? "" : "s"}</p></div><strong>{money(point.gross_minor)}</strong></article>) : <EmptyState title="No revenue in this period" text="Django did not return a settled payment in the selected period." />}</section>
  </>;
}

function Users({ operationsSession }) {
  const [query, setQuery] = useState(""); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  const list = useAsyncData(() => adminControlApi.users({ page, query }), [page, query]);
  return <section className="operations-workspace"><SearchBar label="Search users" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Name or email" />
    {list.loading ? <LoadingPanel /> : list.error ? <ErrorPanel message={list.error} onRetry={list.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Authorized users</h2><span>{list.data.count}</span></div>{list.data.results.length ? list.data.results.map((user) => <button className="operations-row" type="button" key={user.id} onClick={() => setSelected(user.id)}><span className="stat-icon"><Icon name="user" /></span><span><b>{user.full_name || "Unnamed account"}</b><small>{user.email} · {humanize(user.status)}</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No users found" text="No account matched this server-side search." />}</section><Pager page={page} count={list.data.count} onPage={setPage} /></>}
    {selected && <UserDetail userId={selected} operationsSession={operationsSession} onClose={() => setSelected(null)} />}
  </section>;
}

function UserDetail({ userId, operationsSession, onClose }) {
  const detail = useAsyncData(() => adminControlApi.user(userId), [userId]);
  const [reason, setReason] = useState(""); const [pending, setPending] = useState(null); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(null); const [entitlements, setEntitlements] = useState(null);
  async function run(action) { setPending(action); setError(null); try { await adminControlApi.userAction(userId, { action, reason }); detail.reload(); setConfirm(null); } catch (requestError) { setError(requestError); } finally { setPending(null); } }
  if (detail.loading) return <LoadingPanel />;
  if (detail.error) return <ErrorPanel message={detail.error} onRetry={detail.reload} />;
  const user = detail.data; const canManage = hasOperationalCapability(operationsSession, "users.manage"); const canManageRoles = hasOperationalCapability(operationsSession, "operational_roles.manage");
  return <section className="panel operations-detail"><div className="panel-title"><h2>{user.full_name || user.email}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><p className="muted">{user.email} · {humanize(user.status)} · {user.email_verified ? "verified email" : "unverified email"}</p><div className="operations-detail-grid"><div><h3>Roles and access</h3><p>Product: {user.product_roles.join(", ") || "student"}</p><p>Operational: {user.operational_roles.join(", ") || "none"}</p><p>Active sessions: {user.sessions.length}</p></div><div><h3>Learning history</h3><p>{user.learning_activity.focus_sessions.length} recent Focus sessions</p><p>{user.assessments.attempts.length} recent attempts</p><p>{user.subscriptions.length} subscription records</p></div></div><Notice error={error} /><label className="field"><span>Reason required for every account change</span><input value={reason} minLength="8" maxLength="500" onChange={(event) => setReason(event.target.value)} placeholder="Describe the verified administrative reason" /></label>{canManage && <div className="operations-actions"><button className="btn btn-outline compact" type="button" disabled={pending || reason.trim().length < 8} onClick={() => setConfirm(user.status === "suspended" ? "reactivate" : "suspend")}>{user.status === "suspended" ? "Reactivate" : "Suspend"}</button><button className="btn btn-soft compact" type="button" disabled={pending || reason.trim().length < 8} onClick={() => setConfirm(user.email_verified ? "unverify_email" : "verify_email")}>{user.email_verified ? "Unverify email" : "Verify email"}</button><button className="btn btn-soft compact" type="button" disabled={pending || reason.trim().length < 8} onClick={() => setConfirm("logout_all")}>Force logout</button><button className="btn btn-danger compact" type="button" disabled={pending || reason.trim().length < 8} onClick={() => setConfirm("soft_delete")}>Deactivate account</button></div>}<section className="operations-inline-panel"><div className="panel-title"><h3>Focus Workspace access</h3><button className="btn btn-soft compact" type="button" onClick={() => adminControlApi.userEntitlements(userId).then(setEntitlements).catch(setError)}>Inspect</button></div>{entitlements && <>{entitlements.effective_permissions.map((entry) => <p key={entry.code}><b>{entry.code}</b>: {entry.allowed ? "Allowed" : "Denied"} · {entry.reason}</p>)}</>}</section>{canManageRoles && <RoleAccessManager user={user} onUpdated={detail.reload} />}<ConfirmDialog open={Boolean(confirm)} title="Confirm administrative action" message={`Django will ${humanize(confirm)} this account and record your reason in the immutable audit log.`} confirmLabel={pending ? "Working…" : "Confirm"} onCancel={() => setConfirm(null)} onConfirm={() => run(confirm)} /></section>;
}

function RoleAccessManager({ user, onUpdated }) { const data = useAsyncData(() => Promise.all([adminControlApi.roleCatalog(), adminControlApi.userCapabilities(user.id)]).then(([catalog, capabilities]) => ({ catalog, capabilities })), [user.id]); const [selectedRoles, setSelectedRoles] = useState(user.operational_roles || []); const [selectedCapabilities, setSelectedCapabilities] = useState([]); const [selectedProductRoles, setSelectedProductRoles] = useState(user.product_roles || []); const [reason, setReason] = useState(""); const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(null); useEffect(() => { if (data.data) { setSelectedCapabilities(data.data.capabilities.direct_capabilities.map((item) => item.code)); setSelectedRoles(user.operational_roles || []); setSelectedProductRoles(user.product_roles || []); } }, [data.data, user.operational_roles, user.product_roles]); function toggle(value, values, setValues) { setValues(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]); } async function save(kind) { setPending(kind); setError(null); try { if (kind === "operational") await adminControlApi.updateOperationalRoles(user.id, selectedRoles, reason); if (kind === "capabilities") await adminControlApi.updateUserCapabilities(user.id, selectedCapabilities, reason); if (kind === "product") await adminControlApi.userAction(user.id, { action: "replace_product_roles", roles: selectedProductRoles.filter((role) => role !== "student"), reason }); setConfirm(null); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-inline-panel operations-role-manager"><h3>Roles and direct capabilities</h3><p>Role bundles and exceptional direct grants are both enforced by Django. Unknown permissions are denied by default.</p><label className="field"><span>Reason for access change</span><input minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Why is this access required?" /></label><Notice error={error} /><div className="operations-check-grid"><fieldset><legend>Operational roles</legend>{data.data.catalog.operational_roles.map((role) => <label className="check-row" key={role.code}><input type="checkbox" checked={selectedRoles.includes(role.code)} onChange={() => toggle(role.code, selectedRoles, setSelectedRoles)} /> {role.name}</label>)}<button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("operational")}>Save operational roles</button></fieldset><fieldset><legend>Product roles</legend>{data.data.catalog.product_roles.filter((role) => role !== "student").map((role) => <label className="check-row" key={role}><input type="checkbox" checked={selectedProductRoles.includes(role)} onChange={() => toggle(role, selectedProductRoles, setSelectedProductRoles)} /> {humanize(role)}</label>)}<button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("product")}>Save product roles</button></fieldset></div><details><summary>Exceptional direct capabilities ({selectedCapabilities.length})</summary><div className="operations-check-grid">{data.data.capabilities.catalog.map((capability) => <label className="check-row" key={capability.code}><input type="checkbox" checked={selectedCapabilities.includes(capability.code)} onChange={() => toggle(capability.code, selectedCapabilities, setSelectedCapabilities)} /> {capability.name}</label>)}</div><button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("capabilities")}>Save direct capabilities</button></details><ConfirmDialog open={Boolean(confirm)} title="Confirm access change" message="Django will validate the role or capability assignment, protect the final platform administrator, and write an immutable audit record." confirmLabel={pending ? "Saving…" : "Confirm"} onCancel={() => setConfirm(null)} onConfirm={() => save(confirm)} /></section>; }

function EntitlementInspector({ userId, canManage }) { const data = useAsyncData(() => adminControlApi.userEntitlements(userId), [userId]); const [entitlementCode, setEntitlementCode] = useState("focus.workspace"); const [endsAt, setEndsAt] = useState(""); const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function grant() { setPending(true); setError(null); try { await adminControlApi.grantEntitlement(userId, { entitlement_code: entitlementCode, ends_at: endsAt ? new Date(endsAt).toISOString() : null, reason }); setReason(""); setConfirm(false); data.reload(); } catch (requestError) { setError(requestError); } finally { setPending(false); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-inline-panel"><div className="panel-title"><h3>Focus and entitlement inspector</h3><span>Server authority</span></div>{data.data.effective_permissions.map((entry) => <p key={entry.code}><b>{entry.code}</b>: {entry.allowed ? "Allowed" : "Denied"} · {entry.reason}{entry.expires_at ? ` · ends ${shortDate(entry.expires_at)}` : ""}</p>)}<details><summary>Active and historical grants ({data.data.grants.length})</summary>{data.data.grants.map((grant) => <p key={grant.id}>{grant.entitlement?.code || grant.entitlement_code} · {humanize(grant.status)} · {humanize(grant.source_type)}{grant.ends_at ? ` · ends ${shortDate(grant.ends_at)}` : ""}</p>)}</details>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Entitlement code</span><input value={entitlementCode} onChange={(event) => setEntitlementCode(event.target.value)} required /></label><label className="field"><span>Expiry (optional)</span><input type="datetime-local" value={endsAt} onChange={(event) => setEndsAt(event.target.value)} /></label><label className="field"><span>Administrative reason</span><input minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Grant entitlement</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm entitlement grant" message="Django will validate the entitlement definition, calculate effective access, and record an immutable audit event." confirmLabel={pending ? "Working…" : "Grant access"} onCancel={() => setConfirm(false)} onConfirm={grant} /></section>; }

function SearchBar({ label, value, onChange, placeholder }) { return <label className="field operations-search"><span>{label}</span><input type="search" value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} /></label>; }

function Purchases({ operationsSession }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  const data = useAsyncData(() => adminControlApi.purchases({ page, query, status }), [page, query, status]);
  return <section className="operations-workspace"><div className="operations-filter-row"><SearchBar label="Search purchases" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Email, transaction, invoice, plan" /><label className="field"><span>Status</span><select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All</option>{["succeeded", "pending", "failed", "cancelled", "refunded", "partially_refunded"].map((item) => <option value={item} key={item}>{humanize(item)}</option>)}</select></label></div>{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Purchases</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((purchase) => <button className="operations-row" type="button" key={purchase.id} onClick={() => setSelected(purchase.id)}><span className="stat-icon"><Icon name="file" /></span><span><b>{money(purchase.amount_minor, purchase.currency, purchase.currency_exponent)}</b><small>{purchase.user.email || "No account"} · {humanize(purchase.status)} · {purchase.invoice_number || purchase.transaction_id}</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No purchases found" text="No payment matched the Django filters." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}{selected && <PurchaseDetail paymentId={selected} canManage={hasOperationalCapability(operationsSession, "payments.manage")} onClose={() => setSelected(null)} />}</section>;
}

function PurchaseDetail({ paymentId, canManage, onClose }) {
  const data = useAsyncData(() => adminControlApi.purchase(paymentId), [paymentId]); const [amount, setAmount] = useState(""); const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false);
  async function refund() { setPending(true); setError(null); try { await adminControlApi.refund(paymentId, { amountMinor: amount, refundReason: reason }); data.reload(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; const payment = data.data;
  return <section className="panel operations-detail"><div className="panel-title"><h2>Purchase {String(payment.id).slice(0, 8)}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><div className="operations-detail-grid"><div><p><b>{money(payment.amount_minor, payment.currency, payment.currency_exponent)}</b> · {humanize(payment.status)}</p><p>{payment.user.email} · {payment.plan_title || payment.plan_code || "No plan snapshot"}</p><p>Invoice: {payment.invoice?.number || "No invoice"}</p></div><div><p>Provider links: {payment.provider_data?.length || 0}</p><p>Refunded: {money(payment.refunded_amount_minor, payment.currency, payment.currency_exponent)}</p><p>Created {shortDate(payment.created_at)}</p></div></div><section className="operations-inline-panel"><h3>Payment and refund history</h3>{payment.transitions?.map((entry) => <p key={entry.id}>{humanize(entry.from_status || "created")} → {humanize(entry.to_status)} · {shortDate(entry.effective_at)}</p>)}{payment.refunds?.map((refund) => <p key={refund.id}>Refund {money(refund.amount_minor, payment.currency, payment.currency_exponent)} · {humanize(refund.status)}</p>)}</section>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><h3>Request a verified refund</h3><label className="field"><span>Amount in minor currency units</span><input inputMode="numeric" value={amount} onChange={(event) => setAmount(event.target.value)} required /></label><label className="field"><span>Administrative reason</span><input minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Request refund</FormButton></form>}{canManage && <PaymentCorrectionPanel payment={payment} onUpdated={data.reload} />}<ConfirmDialog open={confirm} title="Request refund" message="Django will validate the available refundable balance, call the configured provider, and audit this request." confirmLabel={pending ? "Requesting…" : "Request refund"} onCancel={() => setConfirm(false)} onConfirm={refund} /></section>;
}

function PaymentCorrectionPanel({ payment, onUpdated }) { const [requestedStatus, setRequestedStatus] = useState("failed"); const [reference, setReference] = useState(""); const [reason, setReason] = useState(""); const [reviewReasons, setReviewReasons] = useState({}); const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(false); const [reviewConfirm, setReviewConfirm] = useState(null); async function requestCorrection() { setPending("request"); setError(null); try { await adminControlApi.requestPaymentCorrection(payment.id, { requestedStatus, providerReference: reference, reason }); setConfirm(false); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } async function review(correctionId, decision) { const reviewReason = reviewReasons[correctionId] || ""; setPending(correctionId); setError(null); try { await adminControlApi.reviewPaymentCorrection(correctionId, { decision, reason: reviewReason }); setReviewConfirm(null); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } return <section className="operations-form operations-inline-panel"><h3>Controlled payment reconciliation</h3><p>Payment status is never edited directly. A request must include provider evidence and a different administrator must approve it.</p><label className="field"><span>Requested status</span><select value={requestedStatus} onChange={(event) => setRequestedStatus(event.target.value)}>{["succeeded", "failed", "cancelled"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Verified provider reference</span><input minLength="3" value={reference} onChange={(event) => setReference(event.target.value)} required /></label><label className="field"><span>Request reason</span><input minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><button className="btn btn-outline" type="button" disabled={reference.trim().length < 3 || reason.trim().length < 8 || pending === "request"} onClick={() => setConfirm(true)}>Request independent review</button>{payment.status_corrections?.map((correction) => <article className="operations-campaign" key={correction.id}><div><h3>{humanize(correction.requested_status)} correction · {humanize(correction.status)}</h3><p>{correction.requested_by_name || "Operator"} · {shortDate(correction.created_at)}</p><small>{correction.reason}</small></div>{correction.status === "pending" && <div><input aria-label={`Review reason for correction ${correction.id}`} minLength="8" value={reviewReasons[correction.id] || ""} onChange={(event) => setReviewReasons({ ...reviewReasons, [correction.id]: event.target.value })} placeholder="Independent review reason" /><div className="operations-actions"><button className="btn btn-soft compact" type="button" disabled={pending === correction.id || (reviewReasons[correction.id] || "").trim().length < 8} onClick={() => setReviewConfirm({ id: correction.id, decision: "approve" })}>Approve</button><button className="btn btn-danger compact" type="button" disabled={pending === correction.id || (reviewReasons[correction.id] || "").trim().length < 8} onClick={() => setReviewConfirm({ id: correction.id, decision: "reject" })}>Reject</button></div></div>}</article>)}<ConfirmDialog open={confirm} title="Request independent correction review" message="This will not change payment status. It creates an audited request that a different administrator must review with provider evidence." confirmLabel={pending === "request" ? "Submitting…" : "Submit request"} onCancel={() => setConfirm(false)} onConfirm={requestCorrection} /><ConfirmDialog open={Boolean(reviewConfirm)} title="Confirm correction review" message="Django will enforce separation of duties, validate the payment transition, and record this review in the audit log." confirmLabel={pending ? "Reviewing…" : humanize(reviewConfirm?.decision)} onCancel={() => setReviewConfirm(null)} onConfirm={() => review(reviewConfirm.id, reviewConfirm.decision)} /></section>; }

function Subscriptions({ operationsSession }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  const data = useAsyncData(() => adminControlApi.subscriptions({ page, query, status }), [page, query, status]);
  return <section className="operations-workspace"><div className="operations-filter-row"><SearchBar label="Search subscriptions" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Email or plan" /><label className="field"><span>Status</span><select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All</option>{["active", "trialing", "grace", "expired", "cancelled", "suspended"].map((item) => <option value={item} key={item}>{humanize(item)}</option>)}</select></label></div>{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Subscriptions</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((subscription) => <button className="operations-row" type="button" key={subscription.id} onClick={() => setSelected(subscription.id)}><span className="stat-icon"><Icon name="layers" /></span><span><b>{subscription.plan_title || subscription.plan_code}</b><small>{subscription.user.email || "No account"} · {humanize(subscription.status)} · {subscription.remaining_days ?? "—"} days remaining</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No subscriptions found" text="No subscription matched the Django filters." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}{selected && <SubscriptionDetail subscriptionId={selected} canManage={hasOperationalCapability(operationsSession, "subscriptions.manage")} onClose={() => setSelected(null)} />}</section>;
}

function SubscriptionDetail({ subscriptionId, canManage, onClose }) {
  const data = useAsyncData(() => adminControlApi.subscription(subscriptionId), [subscriptionId]); const [reason, setReason] = useState(""); const [action, setAction] = useState("suspend"); const [expiration, setExpiration] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false);
  async function mutate() { setPending(true); setError(null); try { const body = { action, reason }; if (["extend", "change_expiration"].includes(action)) body.period_ends_at = new Date(expiration).toISOString(); await adminControlApi.subscriptionAction(subscriptionId, body); data.reload(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; const item = data.data;
  return <section className="panel operations-detail"><div className="panel-title"><h2>{item.plan_title || item.plan_code}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><p className="muted">{item.user.email} · {humanize(item.status)} · ends {shortDate(item.current_period_ends_at || item.trial_ends_at)}</p><section className="operations-inline-panel"><h3>Immutable history</h3>{item.admin_events?.length ? item.admin_events.map((event) => <p key={event.id}>{humanize(event.action)} by {event.actor_name || "operator"} · {shortDate(event.created_at)}</p>) : <p>No manual administrative subscription events.</p>}</section>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Subscription action</span><select value={action} onChange={(event) => setAction(event.target.value)}>{["activate", "reactivate", "suspend", "cancel_now", "cancel_period_end", "extend", "change_expiration"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label>{["extend", "change_expiration"].includes(action) && <label className="field"><span>Expiration date</span><input type="datetime-local" value={expiration} onChange={(event) => setExpiration(event.target.value)} required /></label>}<label className="field"><span>Administrative reason</span><input minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Apply change</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm subscription change" message="Django will validate this lifecycle transition, synchronize entitlements, enforce idempotency, and record an immutable event." confirmLabel={pending ? "Applying…" : "Apply change"} onCancel={() => setConfirm(false)} onConfirm={mutate} /></section>;
}

function Notifications({ operationsSession }) {
  const [page, setPage] = useState(1); const [compose, setCompose] = useState(false); const data = useAsyncData(() => adminControlApi.campaigns({ page }), [page]); const canManage = hasOperationalCapability(operationsSession, "notifications.manage");
  return <section className="operations-workspace">{canManage && <button className="btn btn-primary" type="button" onClick={() => setCompose((open) => !open)}><Icon name="megaphone" size={16} /> {compose ? "Close composer" : "Create campaign"}</button>}{compose && <CampaignForm onSaved={() => { setCompose(false); data.reload(); }} />}{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Notification campaigns</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((campaign) => <CampaignRow key={campaign.id} campaign={campaign} canManage={canManage} onChanged={data.reload} />) : <EmptyState title="No campaigns" text="No administrative notification campaign has been created." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}</section>;
}

function ReportsCenter({ operationsSession }) { const [status, setStatus] = useState(""); const [selected, setSelected] = useState(null); const data = useAsyncData(() => adminControlApi.moderationReports({ status }), [status]); const canManage = hasOperationalCapability(operationsSession, "moderation.manage"); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-workspace"><label className="field"><span>Report status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{["open", "triaged", "in_progress", "resolved", "rejected", "duplicate"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><section className="panel list-panel"><div className="panel-title"><h2>Reports and moderation</h2><span>Cursor-paginated</span></div>{data.data.results?.length ? data.data.results.map((report) => <button className="operations-row" type="button" key={report.id} onClick={() => setSelected(report)}><span className="stat-icon"><Icon name="messages" /></span><span><b>{report.target_label || humanize(report.target_type)}</b><small>{humanize(report.reason)} · {humanize(report.status)} · {humanize(report.priority)}</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No reports found" text="No report matches this server-side moderation filter." />}</section>{selected && <ModerationReportDetail report={selected} canManage={canManage} onClose={() => setSelected(null)} onUpdated={() => { setSelected(null); data.reload(); }} />}</section>; }
function ModerationReportDetail({ report, canManage, onClose, onUpdated }) { const [nextStatus, setNextStatus] = useState("triaged"); const [notes, setNotes] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function transition() { setPending(true); setError(null); try { await adminControlApi.transitionModerationReport(report.id, { expected_revision: report.revision, status: nextStatus, resolution_notes: notes }); setConfirm(false); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(false); } } return <section className="panel operations-detail"><div className="panel-title"><h2>{report.target_label || humanize(report.target_type)}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><p>{report.description}</p><p className="muted">Reported by {report.reporter_name} · {humanize(report.reason)} · {humanize(report.priority)}</p>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Moderation status</span><select value={nextStatus} onChange={(event) => setNextStatus(event.target.value)}>{["triaged", "in_progress", "resolved", "rejected"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Resolution note</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} maxLength="4000" /></label><Notice error={error} /><FormButton pending={pending}>Apply moderation decision</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm moderation decision" message="Django will validate the report revision and authorization, record moderation history, and create a platform audit event." confirmLabel={pending ? "Applying…" : "Apply decision"} onCancel={() => setConfirm(false)} onConfirm={transition} /></section>; }

function CampaignForm({ onSaved }) {
  const [form, setForm] = useState({ audience: "all_users", title: "", body: "", send_in_app: true, send_email: false, scheduled_for: "", user_id: "", user_ids: "", plan_code: "", reason: "" });
  const [pending, setPending] = useState(false); const [error, setError] = useState(null);
  function update(key, value) { setForm((current) => ({ ...current, [key]: value })); }
  function audienceFilter() {
    if (form.audience === "user") return { user_id: form.user_id.trim() };
    if (form.audience === "selected_users") return { user_ids: form.user_ids.split(/[\s,]+/).filter(Boolean) };
    if (form.audience === "plan_users") return { plan_code: form.plan_code.trim() };
    return {};
  }
  async function submit(event) { event.preventDefault(); setPending(true); setError(null); try { await adminControlApi.createCampaign({ ...form, scheduled_for: form.scheduled_for ? new Date(form.scheduled_for).toISOString() : null, audience_filter: audienceFilter() }); onSaved(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <form className="panel operations-form" onSubmit={submit}><div className="panel-title"><h2>New campaign</h2><span>Real recipients only</span></div><label className="field"><span>Audience</span><select value={form.audience} onChange={(event) => update("audience", event.target.value)}>{[["all_users", "All active users"], ["active_subscribers", "Active subscribers"], ["expired_subscribers", "Expired subscribers"], ["trial_users", "Trial users"], ["creators", "Creators"], ["user", "One user"], ["selected_users", "Selected users"], ["plan_users", "Users on a plan"]].map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label>{form.audience === "user" && <label className="field"><span>User UUID</span><input value={form.user_id} onChange={(event) => update("user_id", event.target.value)} required /></label>}{form.audience === "selected_users" && <label className="field"><span>User UUIDs</span><textarea value={form.user_ids} onChange={(event) => update("user_ids", event.target.value)} placeholder="One UUID per line or comma-separated" required /></label>}{form.audience === "plan_users" && <label className="field"><span>Plan code</span><input value={form.plan_code} onChange={(event) => update("plan_code", event.target.value)} required /></label>}<label className="field"><span>Title</span><input maxLength="160" value={form.title} onChange={(event) => update("title", event.target.value)} required /></label><label className="field"><span>Message</span><textarea maxLength="320" value={form.body} onChange={(event) => update("body", event.target.value)} required /></label><label className="field"><span>Scheduled delivery (optional)</span><input type="datetime-local" value={form.scheduled_for} onChange={(event) => update("scheduled_for", event.target.value)} /></label><label className="check-row"><input type="checkbox" checked={form.send_in_app} onChange={(event) => update("send_in_app", event.target.checked)} /> In-app notification</label><label className="check-row"><input type="checkbox" checked={form.send_email} onChange={(event) => update("send_email", event.target.checked)} /> Email where configured</label><label className="field"><span>Administrative reason</span><input minLength="8" value={form.reason} onChange={(event) => update("reason", event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Save campaign</FormButton></form>;
}
function CampaignRow({ campaign, canManage, onChanged }) { const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function dispatch() { setPending(true); setError(null); try { await adminControlApi.dispatchCampaign(campaign.id, reason); onChanged(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } } return <article className="operations-campaign"><div><h3>{campaign.title}</h3><p>{humanize(campaign.audience)} · {humanize(campaign.status)} · {campaign.delivered_count} delivered · {campaign.failed_count} failed</p><small>{campaign.body}</small></div>{canManage && ["draft", "scheduled"].includes(campaign.status) && <div><input aria-label={`Reason to dispatch ${campaign.title}`} minLength="8" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Dispatch reason" /><button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || pending} onClick={() => setConfirm(true)}>Dispatch</button><Notice error={error} /></div>}<ConfirmDialog open={confirm} title="Dispatch campaign" message="Django will select the actual audience at dispatch time, track each delivery, and record the operation." confirmLabel={pending ? "Dispatching…" : "Dispatch"} onCancel={() => setConfirm(false)} onConfirm={dispatch} /></article>; }

function AuditLog() { const [page, setPage] = useState(1); const data = useAsyncData(() => adminControlApi.audit({ page }), [page]); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <><section className="panel list-panel"><div className="panel-title"><h2>Immutable audit log</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((record) => <article className="list-row" key={record.id}><span className="stat-icon"><Icon name="activity" /></span><div><h2>{record.action}</h2><p>{record.actor_name || "System"} · {record.reason} · {shortDate(record.occurred_at)}</p></div><span className="pill">{record.domain}</span></article>) : <EmptyState title="No audit records" text="No audit event is visible with your current server permission." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>; }

function ConfigurationEditor({ entry, onSaved }) {
  const [value, setValue] = useState(entry.value);
  const [reason, setReason] = useState("");
  const [error, setError] = useState(null);
  const [pending, setPending] = useState(false);
  const [confirm, setConfirm] = useState(false);

  useEffect(() => { setValue(entry.value); }, [entry.value, entry.version]);

  async function save() {
    setPending(true); setError(null);
    try {
      await adminControlApi.updateConfiguration(entry.key, {
        value,
        expectedVersion: entry.version,
        changeReason: reason
      });
      setReason(""); setConfirm(false); onSaved();
    } catch (requestError) { setError(requestError); }
    finally { setPending(false); }
  }

  const control = entry.value_type === "boolean"
    ? <label className="check-row"><input type="checkbox" checked={Boolean(value)} onChange={(event) => setValue(event.target.checked)} /> Enabled</label>
    : <input type={entry.value_type === "integer" ? "number" : "text"} value={value ?? ""} min={entry.minimum ?? undefined} max={entry.maximum ?? undefined} onChange={(event) => setValue(entry.value_type === "integer" ? Number(event.target.value) : event.target.value)} />;

  return <article className="operations-campaign" key={entry.key}><div><h3>{entry.name || entry.key}</h3><p>{entry.description || entry.key}</p><small>Version {entry.version}{entry.updated_at ? ` · Updated ${shortDate(entry.updated_at)}` : ""}</small></div><form className="operations-setting-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Value</span>{control}</label><label className="field"><span>Administrative reason</span><input minLength="8" maxLength="500" value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending} className="btn btn-soft compact">Save</FormButton></form><ConfirmDialog open={confirm} title="Confirm platform setting" message="Django will validate this typed setting, reject a stale version, and create an immutable audit record." confirmLabel={pending ? "Saving…" : "Save setting"} onCancel={() => setConfirm(false)} onConfirm={save} /></article>;
}

function SettingsArea({ operationsSession }) {
  const data = useAsyncData(() => adminControlApi.configurations(), []);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const entries = data.data.results || data.data;
  const canManage = hasOperationalCapability(operationsSession, "configuration.manage");
  return <section className="panel list-panel"><div className="panel-title"><h2>Platform settings</h2><span>{canManage ? "Controlled changes" : "Read only"}</span></div>{Array.isArray(entries) && entries.length ? entries.map((entry) => canManage ? <ConfigurationEditor key={entry.key} entry={entry} onSaved={data.reload} /> : <article className="list-row" key={entry.key}><span className="stat-icon"><Icon name="settings" /></span><div><h2>{entry.name || entry.key}</h2><p>{entry.description || entry.key}</p></div><span className="pill">{String(entry.value)}</span></article>) : <EmptyState title="No settings available" text="Django did not return non-secret configuration entries for this role." />}</section>;
}

function SystemStatus() { const data = useAsyncData(() => adminControlApi.systemHealth(), []); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="panel operations-health"><div className="panel-title"><h2>System status</h2><span>Redacted health information</span></div><pre>{JSON.stringify(data.data, null, 2)}</pre></section>; }

function Exports() { const data = useAsyncData(() => adminControlApi.reports(), []); const [status, setStatus] = useState(""); const [error, setError] = useState(null); async function download(report, format) { setStatus(`${report.code}:${format}`); setError(null); try { const preview = await adminControlApi.previewReport(report.code, {}, format); const blob = await adminControlApi.executeReport(preview.id, preview.confirmation_token); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${report.code}.${format}`; link.click(); URL.revokeObjectURL(url); } catch (requestError) { setError(requestError); } finally { setStatus(""); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="panel list-panel"><div className="panel-title"><h2>Secure exports</h2><span>CSV or Excel</span></div><Notice error={error} />{data.data.results?.length ? data.data.results.map((report) => <article className="list-row" key={report.code}><span className="stat-icon"><Icon name="file" /></span><div><h2>{report.name}</h2><p>{report.description}</p></div><div className="operations-actions"><button className="btn btn-soft compact" type="button" disabled={Boolean(status)} onClick={() => download(report, "csv")}>{status === `${report.code}:csv` ? "Preparing…" : "CSV"}</button><button className="btn btn-outline compact" type="button" disabled={Boolean(status)} onClick={() => download(report, "xlsx")}>{status === `${report.code}:xlsx` ? "Preparing…" : "Excel"}</button></div></article>) : <EmptyState title="No exports available" text="Django has not granted an export report to this operational role." />}</section>; }

function Plans() { const data = useAsyncData(() => adminControlApi.plans(), []); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="panel list-panel"><div className="panel-title"><h2>Subscription plans</h2><span>Server-defined</span></div>{data.data.results?.length ? data.data.results.map((plan) => <article className="list-row" key={plan.id}><span className="stat-icon"><Icon name="layers" /></span><div><h2>{plan.code}</h2><p>{humanize(plan.status)} · {plan.versions?.length || 0} version{plan.versions?.length === 1 ? "" : "s"}</p></div><span className="pill">{plan.product?.title}</span></article>) : <EmptyState title="No plans" text="Django has not returned any subscription plans." />}</section>; }

export default function OperationsAdmin({ operationsSession }) {
  const location = useLocation(); const navigate = useNavigate();
  const requested = location.pathname.split("/").filter(Boolean).at(-1);
  const allowed = useMemo(() => TABS.filter(([, , capability]) => hasOperationalCapability(operationsSession, capability)), [operationsSession]);
  const active = allowed.some(([key]) => key === requested) ? requested : allowed[0]?.[0] || "overview";
  useEffect(() => { if (allowed.length && requested !== active) navigate(`/operations/admin/${active}`, { replace: true }); }, [active, allowed.length, navigate, requested]);
  const content = active === "overview" ? <Overview /> : active === "users" ? <Users operationsSession={operationsSession} /> : active === "purchases" ? <Purchases operationsSession={operationsSession} /> : active === "subscriptions" ? <><Subscriptions operationsSession={operationsSession} /><Plans /></> : active === "notifications" ? <Notifications operationsSession={operationsSession} /> : active === "reports" ? <ReportsCenter operationsSession={operationsSession} /> : active === "audit" ? <AuditLog /> : active === "settings" ? <SettingsArea operationsSession={operationsSession} /> : active === "system" ? <SystemStatus /> : active === "exports" ? <Exports /> : <ErrorPanel message="This operational area is not available for the current server permission." />;
  return <Page title="Operations console" showHeading={false}><AdminTabs operationsSession={operationsSession} active={active} />{content}</Page>;
}
